import React, { useState, useEffect } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate } from 'react-router-dom';

export default function Blog() {
    const navigate = useNavigate();
    const [activeCategory, setActiveCategory] = useState('all');
    const [expandedArticle, setExpandedArticle] = useState(null);

    // Force body to be scrollable when this component mounts
    useEffect(() => {
        document.body.style.overflow = 'auto';
        document.documentElement.style.overflow = 'auto';
        return () => {
            document.body.style.overflow = '';
            document.documentElement.style.overflow = '';
        };
    }, []);

    const scrollToTop = () => {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const categories = [
        { id: 'all', name: 'All' },
        { id: 'python', name: '🐍 Python' },
        { id: 'c-cpp', name: '⚡ C/C++' },
        { id: 'history', name: '📜 History' },
        { id: 'wow', name: '🚀 Wow/Futuristic' },
    ];

    const articles = [
        {
            id: 1,
            title: 'The Birth of Python: How a Christmas Project Changed Programming Forever',
            category: 'history',
            excerpt: 'In December 1989, Guido van Rossum started a hobby project during his Christmas break. He had no idea that this "side project" would become one of the most popular programming languages on Earth...',
            content: `In the winter of 1989, while working at the Centrum Wiskunde & Informatica (CWI) in the Netherlands, Guido van Rossum found himself with extra time during the Christmas holidays. His colleagues were gone, the office was quiet, and he needed a creative outlet.

He had been working on the Amoeba distributed operating system and wanted to use a scripting language. But existing options like Perl and ABC (a language he helped develop) had limitations. So he decided to create his own.

The name "Python" wasn't chosen because of the snake. Van Rossum was a fan of the British comedy group Monty Python. He wanted a name that was short, unique, and slightly mysterious. And so, Python was born.

By February 1991, Python 0.9.0 was released to the world on alt.sources. It already had classes, exception handling, functions, and the core data types that Python developers still use today.

Today, Python is the #1 language for data science, AI, and education. It runs on Mars (NASA's Perseverance rover), powers Netflix's recommendation engine, and is the first language taught at MIT and Stanford.`,
            readTime: 5,
            date: 'Dec 25, 1989',
            image: 'https://upload.wikimedia.org/wikipedia/commons/c/c3/Python-logo-notext.svg',
            author: 'Guido van Rossum',
            color: '#3776AB'
        },
        {
            id: 2,
            title: 'C: The God Language That Still Rules the World',
            category: 'c-cpp',
            excerpt: 'Created in 1972 by Dennis Ritchie, C is like Latin for programming - almost everything modern is built on its foundations...',
            content: `Before C, operating systems were written in assembly language. Each computer needed a completely rewritten OS. Then came Dennis Ritchie at Bell Labs.

The year was 1972. Ritchie and Ken Thompson were working on Unix. They needed a language that was powerful like assembly but portable across different machines. The result? C.

C gave programmers an unprecedented combination: high-level convenience with low-level control. You could manipulate memory directly, create efficient algorithms, and still write readable code.

Even today, C ranks in the top 5 languages (TIOBE Index). Embedded systems, operating systems, game engines, and high-performance computing still rely on C.`,
            readTime: 6,
            date: '1972',
            image: 'https://upload.wikimedia.org/wikipedia/commons/1/19/C_Logo.png',
            author: 'Dennis Ritchie',
            color: '#00599C'
        },
        {
            id: 3,
            title: 'The First Programmer Was a Woman: Ada Lovelace',
            category: 'history',
            excerpt: 'In 1843, Ada Lovelace wrote the world\'s first computer algorithm. She imagined computers doing art, music, and AI - a century before anyone else...',
            content: `Long before Silicon Valley, before Microsoft or Apple, there was Ada Lovelace. Born in 1815 to the famous poet Lord Byron, Ada's mother insisted she study mathematics.

At 17, Ada met Charles Babbage, who had designed the Analytical Engine - the world's first mechanical computer concept. While others saw a glorified calculator, Ada saw something revolutionary.

In 1843, she wrote what historians now recognize as the first computer program: a sequence of operations to calculate Bernoulli numbers. She even anticipated concepts like looping and subroutines.

Today, Ada Lovelace Day celebrates women in STEM. The U.S. Department of Defense named a programming language "Ada" in her honor.`,
            readTime: 5,
            date: '1843',
            image: 'https://upload.wikimedia.org/wikipedia/commons/8/87/Ada_Lovelace.jpg',
            author: 'Ada Lovelace',
            color: '#9b4d96'
        },
        {
            id: 4,
            title: 'The ENIAC Programmers: History\'s Forgotten Heroes',
            category: 'history',
            excerpt: 'Six women programmed the world\'s first general-purpose computer. They were the best mathematicians of their generation. And for 50 years, history forgot them...',
            content: `In 1945, the U.S. Army needed to calculate artillery firing tables - complex trajectories that took 40 hours to compute by hand.

The solution was ENIAC, the world's first general-purpose electronic computer. It weighed 30 tons and filled a whole room.

Six women - Kay McNulty, Betty Jennings, Betty Snyder, Marlyn Meltzer, Fran Bilas, and Ruth Lichterman - made it work. They had no programming languages, no manuals. They programmed by physically plugging wires.

Their work was brilliant. They developed techniques like breakpoints and subroutines still used today. But at the celebration dinner, the women were not introduced. The men received all the credit.

In 1997, they were finally inducted into the Women in Technology International Hall of Fame.`,
            readTime: 6,
            date: '1945',
            image: 'https://upload.wikimedia.org/wikipedia/commons/8/8b/Eniac.jpg',
            author: 'ENIAC Programmers',
            color: '#2c3e50'
        },
        {
            id: 5,
            title: 'C++: The Language That Runs the World',
            category: 'c-cpp',
            excerpt: 'Your web browser? C++. Your video games? C++. Photoshop? C++. Meet the unsung hero of modern computing...',
            content: `In 1979, Bjarne Stroustrup created "C with Classes." By 1983, it had a new name: C++.

C++ gave developers object-oriented programming without sacrificing C's raw speed. The 1990s were C++'s golden age. Microsoft built Windows on C++. Adobe built Photoshop on C++.

Today, C++ powers: Web browsers (Chrome, Firefox), Databases (MySQL, MongoDB), Trading Systems (Wall Street), Game Engines (Unreal), and more.

Bjarne Stroustrup famously said: "There are only two kinds of languages: the ones people complain about and the ones nobody uses." People complain about C++ because they USE it.`,
            readTime: 6,
            date: '1983',
            image: 'https://upload.wikimedia.org/wikipedia/commons/1/18/ISO_C%2B%2B_Logo.svg',
            author: 'Bjarne Stroustrup',
            color: '#f34b7d'
        },
        {
            id: 6,
            title: 'Python\'s Hidden Magic: Metaclasses Explained',
            category: 'python',
            excerpt: 'Python is simple, right? Wait until you discover metaclasses - code that writes code...',
            content: `Behind Python's simple syntax lies one of the most sophisticated metaprogramming systems ever created.

**Decorators**: Functions that modify functions - used by Flask, Django, pytest.

**Descriptors**: Power @property and SQLAlchemy's column definitions.

**Metaclasses**: Intercept class creation itself. Django uses them to turn model definitions into database schemas.

These features are why Python powers both tiny scripts and massive systems like Instagram (over a billion users).`,
            readTime: 7,
            date: '2024',
            image: 'https://upload.wikimedia.org/wikipedia/commons/c/c3/Python-logo-notext.svg',
            author: 'Python Core Devs',
            color: '#3776AB'
        },
        {
            id: 7,
            title: 'Quantum Programming: Coding for the Future',
            category: 'wow',
            excerpt: 'Google\'s quantum computer solved a problem in 200 seconds that would take a supercomputer 10,000 years...',
            content: `In 2019, Google's Sycamore quantum computer achieved "quantum supremacy."

Quantum bits (qubits) can be 0, 1, or ANY combination simultaneously. A quantum computer with 300 qubits can process 2^300 states at once.

**Quantum Languages**: Qiskit (IBM), Cirq (Google), Microsoft Q#, Amazon Braket.

Applications: Cryptography (breaking RSA), Drug Discovery, Climate Modeling, Machine Learning.

You can access real quantum computers for free through IBM's Quantum Experience.`,
            readTime: 7,
            date: '2024',
            image: 'https://upload.wikimedia.org/wikipedia/commons/f/f6/IBM_Quantum_Computer.jpg',
            author: 'Quantum Dev Team',
            color: '#6a1b9a'
        },
        {
            id: 8,
            title: 'The Thompson Hack: The Most Genius Virus Ever',
            category: 'history',
            excerpt: 'Ken Thompson built a virus that couldn\'t be detected - even by reading the source code...',
            content: `In 1983, Ken Thompson gave a Turing Award speech titled "Reflections on Trusting Trust."

He imagined modifying the C compiler to insert a backdoor into the Unix login program, AND to insert code that continues this injection when the compiler recompiles itself.

Even if you review every line of source code, you cannot detect this attack. The compiler binary is compromised.

Thompson concluded: "You can't trust code that you did not totally create yourself."`,
            readTime: 6,
            date: '1983',
            image: 'https://upload.wikimedia.org/wikipedia/commons/4/4a/Ken_Thompson_%28scientist%29.jpg',
            author: 'Ken Thompson',
            color: '#d35400'
        }
    ];

    const filteredArticles = activeCategory === 'all'
        ? articles
        : articles.filter(a => a.category === activeCategory);

    return (
        <>
            <Helmet>
                <title>CyberCode Blog - Programming History & Tech Stories</title>
                <meta name="description" content="Fascinating articles about programming history, Python, C++, and mind-blowing tech stories." />
            </Helmet>

            {/* Simple wrapper - no flex, no height restrictions */}
            <div style={{ background: 'var(--bg-primary)' }}>
                {/* Content container */}
                <div style={{ padding: '60px 20px', maxWidth: '1200px', margin: '0 auto' }}>
                    <button onClick={() => navigate('/')} style={{
                        background: 'rgba(0,245,255,0.1)',
                        border: '1px solid var(--accent-cyan)',
                        color: 'var(--accent-cyan)',
                        padding: '8px 20px',
                        borderRadius: '30px',
                        fontSize: '12px',
                        cursor: 'pointer',
                        marginBottom: '32px',
                        fontFamily: 'var(--font-mono)',
                    }}>← BACK TO HOME</button>

                    <div style={{ textAlign: 'center', marginBottom: '48px' }}>
                        <h1 style={{ fontSize: '48px', fontWeight: 'bold', color: 'var(--accent-cyan)', fontFamily: 'var(--font-mono)', marginBottom: '16px' }}>
                            CYBERCODE BLOG
                        </h1>
                        <p style={{ color: 'var(--text-secondary)', fontSize: '16px', maxWidth: '700px', margin: '0 auto' }}>
                            Deep dives into programming history, language internals, and the future of code
                        </p>
                        <div style={{ height: '2px', background: 'linear-gradient(90deg, transparent, var(--accent-cyan), transparent)', width: '300px', margin: '24px auto' }} />
                    </div>

                    {/* Categories */}
                    <div style={{
                        display: 'flex',
                        flexWrap: 'wrap',
                        justifyContent: 'center',
                        gap: '12px',
                        marginBottom: '48px',
                    }}>
                        {categories.map(cat => (
                            <button
                                key={cat.id}
                                onClick={() => {
                                    setActiveCategory(cat.id);
                                    setExpandedArticle(null);
                                }}
                                style={{
                                    background: activeCategory === cat.id ? 'linear-gradient(90deg, var(--accent-cyan), #00aacc)' : 'rgba(0,245,255,0.1)',
                                    border: `1px solid ${activeCategory === cat.id ? 'transparent' : 'var(--accent-cyan)'}`,
                                    color: activeCategory === cat.id ? '#000' : 'var(--accent-cyan)',
                                    padding: '10px 24px',
                                    borderRadius: '40px',
                                    fontSize: '14px',
                                    fontWeight: 'bold',
                                    cursor: 'pointer',
                                    transition: '0.2s',
                                }}
                            >
                                {cat.name}
                            </button>
                        ))}
                    </div>

                    {/* Articles Grid */}
                    <div style={{
                        display: 'grid',
                        gridTemplateColumns: 'repeat(auto-fill, minmax(380px, 1fr))',
                        gap: '28px',
                        marginBottom: '48px',
                    }}>
                        {filteredArticles.map(article => (
                            <div key={article.id} style={{
                                background: 'rgba(0, 20, 30, 0.6)',
                                border: `1px solid ${expandedArticle === article.id ? 'var(--accent-cyan)' : 'rgba(0, 245, 255, 0.2)'}`,
                                borderRadius: '16px',
                                overflow: 'hidden',
                                transition: '0.3s',
                                cursor: 'pointer',
                            }}
                                 onClick={() => setExpandedArticle(expandedArticle === article.id ? null : article.id)}>
                                <div style={{
                                    height: '180px',
                                    background: `linear-gradient(135deg, ${article.color}20, ${article.color}05)`,
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    overflow: 'hidden',
                                    position: 'relative',
                                }}>
                                    <img
                                        src={article.image}
                                        alt={article.title}
                                        style={{
                                            height: '80px',
                                            objectFit: 'contain',
                                            opacity: 0.85,
                                        }}
                                        onError={(e) => {
                                            e.target.style.display = 'none';
                                        }}
                                    />
                                    <div style={{
                                        position: 'absolute',
                                        top: '12px',
                                        right: '12px',
                                        background: 'rgba(0,0,0,0.6)',
                                        padding: '4px 10px',
                                        borderRadius: '20px',
                                        fontSize: '11px',
                                        color: 'var(--accent-cyan)',
                                    }}>
                                        {article.readTime} min read
                                    </div>
                                </div>
                                <div style={{ padding: '20px' }}>
                                    <h3 style={{ color: 'var(--accent-cyan)', fontSize: '18px', fontWeight: 'bold', lineHeight: '1.3', marginBottom: '12px' }}>{article.title}</h3>
                                    <div style={{ display: 'flex', gap: '12px', marginBottom: '12px', fontSize: '11px', color: 'var(--text-muted)' }}>
                                        <span>📅 {article.date}</span>
                                        <span>✍️ {article.author}</span>
                                    </div>
                                    <p style={{ color: 'var(--text-secondary)', fontSize: '13px', marginBottom: '16px', lineHeight: '1.6' }}>
                                        {expandedArticle === article.id ? article.content : article.excerpt}
                                    </p>
                                    <div style={{
                                        color: 'var(--accent-cyan)',
                                        fontSize: '12px',
                                        textAlign: 'center',
                                        paddingTop: '8px',
                                        borderTop: '1px solid rgba(0,245,255,0.2)',
                                    }}>
                                        {expandedArticle === article.id ? '▲ CLICK TO COLLAPSE' : '▼ CLICK TO READ FULL ARTICLE'}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Newsletter */}
                    <div style={{
                        background: 'linear-gradient(135deg, rgba(0,245,255,0.1), rgba(0,170,204,0.05))',
                        border: '1px solid rgba(0, 245, 255, 0.3)',
                        borderRadius: '20px',
                        padding: '40px',
                        textAlign: 'center',
                        marginBottom: '40px',
                    }}>
                        <h3 style={{ color: 'var(--accent-cyan)', fontSize: '24px', marginBottom: '12px' }}>Never Miss a Story</h3>
                        <p style={{ color: 'var(--text-secondary)', marginBottom: '24px' }}>Get weekly programming insights delivered to your inbox</p>
                        <div style={{ display: 'flex', gap: '12px', justifyContent: 'center', flexWrap: 'wrap' }}>
                            <input
                                type="email"
                                placeholder="your@email.com"
                                style={{
                                    background: 'rgba(0,0,0,0.4)',
                                    border: '1px solid var(--accent-cyan)',
                                    padding: '12px 20px',
                                    borderRadius: '30px',
                                    color: 'var(--text-primary)',
                                    width: '280px',
                                    fontSize: '14px',
                                }}
                            />
                            <button style={{
                                background: 'linear-gradient(90deg, var(--accent-cyan), #00aacc)',
                                color: '#000',
                                border: 'none',
                                padding: '12px 28px',
                                borderRadius: '30px',
                                fontWeight: 'bold',
                                cursor: 'pointer',
                            }}>Subscribe →</button>
                        </div>
                        <p style={{ color: 'var(--text-muted)', fontSize: '11px', marginTop: '16px' }}>No spam. Unsubscribe anytime.</p>
                    </div>

                    {/* Footer */}
                    <div style={{
                        background: 'rgba(0, 5, 10, 0.95)',
                        backdropFilter: 'blur(8px)',
                        borderTop: '1px solid rgba(0, 245, 255, 0.4)',
                        borderRadius: '16px',
                        textAlign: 'center',
                        padding: '28px 24px 24px',
                        marginTop: '20px',
                    }}>
                        <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'space-between', alignItems: 'center', gap: '20px' }}>
                            <div style={{ textAlign: 'left' }}>
                                <div style={{ fontSize: '14px', fontWeight: 'bold', color: 'var(--accent-cyan)', marginBottom: '8px' }}>CYBERCODE</div>
                                <div style={{ fontSize: '11px', color: 'var(--text-muted)' }}>© 2025 Cybercode Labs</div>
                            </div>
                            <div style={{ display: 'flex', gap: '28px', flexWrap: 'wrap', justifyContent: 'center' }}>
                                <button onClick={() => navigate('/about')} style={{ color: 'var(--text-secondary)', fontSize: '12px', background: 'none', border: 'none', cursor: 'pointer' }}>About</button>
                                <button onClick={() => navigate('/docs')} style={{ color: 'var(--text-secondary)', fontSize: '12px', background: 'none', border: 'none', cursor: 'pointer' }}>Docs</button>
                                <button onClick={() => navigate('/community')} style={{ color: 'var(--text-secondary)', fontSize: '12px', background: 'none', border: 'none', cursor: 'pointer' }}>Community</button>
                                <button onClick={() => navigate('/support')} style={{ color: 'var(--text-secondary)', fontSize: '12px', background: 'none', border: 'none', cursor: 'pointer' }}>Support</button>
                                <button onClick={() => navigate('/blog')} style={{ color: 'var(--accent-cyan)', fontSize: '12px', background: 'none', border: 'none', cursor: 'pointer' }}>Blog</button>
                            </div>
                            <button onClick={scrollToTop} style={{ background: 'rgba(0,245,255,0.1)', border: '1px solid var(--accent-cyan)', color: 'var(--accent-cyan)', padding: '6px 14px', borderRadius: '30px', fontSize: '11px', cursor: 'pointer' }}>▲ BACK TO TOP</button>
                        </div>
                    </div>
                </div>
            </div>
        </>
    );
}
